CREATE DATABASE customer_shopping;
USE customer_shopping;
show tables;
desc customer_shopping_behavior;

ALTER TABLE customer_shopping_behavior
RENAME column `ï»¿customer_id` TO customer_id;

ALTER TABLE customer_shopping_behavior
RENAME column `purchase_amount_(usd)` TO purchase_amount_in_usd;

-- total revenue generated by male vs female customers.
SELECT gender, SUM(purchase_amount_in_usd) AS total_revenue FROM customer_shopping_behavior GROUP BY 1 ;
SELECT * FROM customer_shopping_behavior limit 4;

-- customers with discount but still spend greater than the avergae amount
SELECT customer_id, concat("$ ",purchase_amount_in_usd) FROM customer_shopping_behavior
WHERE discount_applied = "Yes" AND purchase_amount_in_usd >(SELECT AVG(purchase_amount_in_usd) FROM customer_shopping_behavior) ;

-- top 5 products with highest average review rating

SELECT item_purchased as product, ROUND(AVG(review_rating),2) as average_review_rating from customer_shopping_behavior group by 1 order by 2 desc limit 5;

-- average purchase amounts between standard and express shipping
SELECT shipping_type, CONCAT("$",ROUND(AVG(purchase_amount_in_usd),2)) FROM customer_shopping_behavior WHERE shipping_type IN ("Standard", "Express") GROUP BY 1;

-- AVg spend between subs and non subs

select case when subscription_status = "Yes" THEN "Subscriber" 
else "Non-Subscriber" end  AS subscription_status, count(*) as  total_customers, CONCAT("$",ROUND(AVG(purchase_amount_in_usd),2)) AS avg_spend,
CONCAT("$",ROUND(SUM(purchase_amount_in_usd),2)) AS total_revenue from customer_shopping_behavior group by 1; 

-- TOP 5 PRODUCTS with high percentage of purchases with discount appied
SELECT * from customer_shopping_behavior;

SELECT item_purchased AS product, (count(*)/(select COUNT(*) from customer_shopping_behavior c WHERE C.item_purchased = d.item_purchased ))*100 as percentage
 from customer_shopping_behavior d WHERE discount_applied = "Yes" group by 1 order by 2 desc limit 5;
 
 -- more optimised
 SELECT item_purchased AS product, round(SUM(CASE WHEN discount_applied = "Yes" THEN 1 ELSE 0 end)/count(*)* 100,2)
as percentage
 from customer_shopping_behavior group by 1 order by 2 desc limit 5;
 
-- segment customers into new, returning and loya customers based on their total number of previous purchases and their count
SELECT CASE WHEN previous_purchases = 1 THEN 'New' 
 when previous_purchases between 2 and 10 then 'Returning' 
 ELSE 'Loyal' end as customer_segment,sum(previous_purchases) as total_previous_purchases, COUNT(*) as nuumber_of_customers from customer_shopping_behavior group by 1;
 
-- three most purchased projects within each category
WITH CTE AS (select category, item_purchased, COUNT(*) AS total_purcashes , ROW_NUMBER() OVER (PARTITION BY category ORDER BY COUNT(*) DESC) AS RANKER
FROM customer_shopping_behavior group by 1, 2 ORDER BY 1, 4)
SELECT RANKER AS item_rank, category, item_purchased, total_purcashes from cte where RANKER <=3;

-- are customers who are repeat customers (more than 5 previous purchases) also likely to subscribe

SELECT CASE WHEN previous_purchases > 5 THEN "Loyal" else "non_loyal" end as loyality, SUM(CASE WHEN subscription_status = "Yes" THEN 1 ELSE 0 END) AS subsriber_count,
SUM(CASE WHEN subscription_status = "Yes" THEN 0 ELSE 1 END) AS non_subsriber_count, count(*) as total_count
from customer_shopping_behavior group by 1;

SELECT subscription_status, COUNT(*) as repeat_buyers from customer_shopping_behavior where previous_purchases> 5  GROUP BY 1 ORDER BY 2 DESC;
-- revenue contribustion of each age group
SELECT * FROM customer_shopping_behavior limit 1;
SELECT age_group, SUM(purchase_amount_in_usd) total_revenue from customer_shopping_behavior group by 1 order by 2 desc;



